import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long h = Long.parseLong(next());
        long w = Long.parseLong(next());
        long[][] gold = new long[(int) h][(int) w];
        for (int i = 0; i < gold.length; i++) {
            for (int j = 0; j < gold[i].length; j++) {
                gold[i][j] = Long.parseLong(next());
            }
        }

        int rowsCount = (int) h, colsCount = (int) w;
        long[] best = new long[rowsCount];
        long[] next = new long[rowsCount];
        for (int i = 0; i < rowsCount; i++) best[i] = gold[i][0];
        for (int j = 1; j < colsCount; j++) {
            for (int i = 0; i < rowsCount; i++) {
                long top = best[i];
                if (i > 0) top = Math.max(top, best[i - 1]);
                if (i + 1 < rowsCount) top = Math.max(top, best[i + 1]);
                next[i] = top + gold[i][j];
            }
            long[] swap = best;
            best = next;
            next = swap;
        }
        long answer = best[0];
        for (long x : best) answer = Math.max(answer, x);
        System.out.println(answer);
    }
}
